(async () => {
    "use strict";

    /* =========================================================
     * 0. 停止旧版本
     * ========================================================= */

    try {
        if (typeof window.stopSatisfactionMonitor === "function") {
            window.stopSatisfactionMonitor();
        }
    } catch (error) {
        console.warn("停止旧监控时出现提示：", error);
    }

    try {
        const oldWindow = window.__SATISFACTION_FLOAT_WINDOW__;

        if (oldWindow && !oldWindow.closed) {
            oldWindow.close();
        }
    } catch (error) {
        console.warn("关闭旧浮窗时出现提示：", error);
    }

    if (window.self !== window.top) {
        console.error(
            "当前 Console 运行在 iframe。请在 Console 顶部执行环境中选择 top 后重新运行。"
        );
        return;
    }

    /* =========================================================
     * 1. 配置
     * ========================================================= */

    const SETTINGS_KEY = "satisfaction-monitor-settings-v2";

    const DEFAULT_SETTINGS = {
        excludedEmployeePrefixes: ["WX", "84"],
        targetScore: 97,
        refreshIntervalSeconds: 5,
        criticalThreshold: 3.5,
        secondaryThreshold: 5
    };

    const CONFIG = {
        listApiBase:
            "https://w3.huawei.com/iadmin/saas/gateway/com.huawei.iadmin.saas.catering:catering_general/catering/general/services/accounting/publicitySatisfaction/getSatisfactionList",

        detailApi:
            "https://w3.huawei.com/iadmin/saas/gateway/com.huawei.iadmin.saas.catering:catering_general/catering/general/services/accounting/publicitySatisfaction/exportDetailsMultiSheet",

        xlsxScriptUrls: [
            "https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js",
            "https://unpkg.com/xlsx@0.18.5/dist/xlsx.full.min.js"
        ],

        pageSize: 100,
        queryMonths: 6,

        minInterval: 3000,
        maxInterval: 5000,

        passScore: 97,

        restaurants: {
            SV: ["SV餐厅", "SV"],
            CFC: ["CFC餐厅", "CFC"]
        },

        monitorWindow: {
            width: 470,
            height: 455
        },

        detailWindow: {
            width: 1100,
            height: 780
        },

        maxStoredEvents: 100,
        autoDownloadWhenParseFails: true
    };

    /* =========================================================
     * 2. 工具函数
     * ========================================================= */

    function sleep(milliseconds) {
        return new Promise(resolve => setTimeout(resolve, milliseconds));
    }

    function escapeHtml(value) {
        return String(value ?? "")
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }

    function normalizeText(value) {
        return String(value ?? "")
            .trim()
            .toUpperCase()
            .replace(/\s+/g, "");
    }

    function normalizeHeader(value) {
        return String(value ?? "")
            .replace(/\r?\n/g, " ")
            .replace(/\s+/g, " ")
            .trim();
    }

    function normalizeEmployeeNumber(value) {
        return String(value ?? "")
            .trim()
            .toUpperCase()
            .replace(/[\s_-]+/g, "");
    }

    function normalizePrefix(value) {
        return String(value ?? "")
            .trim()
            .toUpperCase()
            .replace(/[\s_-]+/g, "");
    }

    function normalizePrefixList(values) {
        return [
            ...new Set(
                (Array.isArray(values) ? values : [])
                    .map(normalizePrefix)
                    .filter(Boolean)
            )
        ];
    }

    function parsePrefixText(value) {
        return normalizePrefixList(
            String(value ?? "")
                .split(/[\s,，;；、\n\r]+/)
                .filter(Boolean)
        );
    }

    function loadSettings() {
        try {
            const saved = JSON.parse(
                localStorage.getItem(SETTINGS_KEY) || "{}"
            );

            const prefixes = normalizePrefixList(
                Array.isArray(saved.excludedEmployeePrefixes)
                    ? saved.excludedEmployeePrefixes
                    : DEFAULT_SETTINGS.excludedEmployeePrefixes
            );

            const targetScore = typeof saved.targetScore === "number" && saved.targetScore >= 0 && saved.targetScore <= 100 
                ? saved.targetScore 
                : DEFAULT_SETTINGS.targetScore;

            const refreshIntervalSeconds = typeof saved.refreshIntervalSeconds === "number" && saved.refreshIntervalSeconds >= 1 
                ? saved.refreshIntervalSeconds 
                : DEFAULT_SETTINGS.refreshIntervalSeconds;

            const criticalThreshold = typeof saved.criticalThreshold === "number"
                ? saved.criticalThreshold
                : DEFAULT_SETTINGS.criticalThreshold;

            const secondaryThreshold = typeof saved.secondaryThreshold === "number"
                ? saved.secondaryThreshold
                : DEFAULT_SETTINGS.secondaryThreshold;

            return {
                excludedEmployeePrefixes:
                    prefixes.length > 0
                        ? prefixes
                        : DEFAULT_SETTINGS.excludedEmployeePrefixes.slice(),
                targetScore,
                refreshIntervalSeconds,
                criticalThreshold,
                secondaryThreshold
            };
        } catch (error) {
            console.warn("读取设置失败，使用默认值：", error);

            return {
                excludedEmployeePrefixes:
                    DEFAULT_SETTINGS.excludedEmployeePrefixes.slice(),
                targetScore: DEFAULT_SETTINGS.targetScore,
                refreshIntervalSeconds: DEFAULT_SETTINGS.refreshIntervalSeconds,
                criticalThreshold: DEFAULT_SETTINGS.criticalThreshold,
                secondaryThreshold: DEFAULT_SETTINGS.secondaryThreshold
            };
        }
    }

    function saveSettings() {
        localStorage.setItem(
            SETTINGS_KEY,
            JSON.stringify(state.settings)
        );
    }

    function cleanCell(value) {
        return String(value ?? "").trim();
    }

    function toNumber(value) {
        if (
            value === null ||
            value === undefined ||
            value === ""
        ) {
            return null;
        }

        const normalized =
            typeof value === "string"
                ? value.replace(/,/g, "").trim()
                : value;

        const number = Number(normalized);

        return Number.isFinite(number) ? number : null;
    }

    function round(value, digits = 2) {
        if (!Number.isFinite(value)) {
            return null;
        }

        const factor = 10 ** digits;

        return (
            Math.round((value + Number.EPSILON) * factor) /
            factor
        );
    }

    function formatScore(value) {
        return Number.isFinite(value)
            ? value.toFixed(2)
            : "--";
    }

    function formatInteger(value) {
        return Number.isFinite(value)
            ? String(value)
            : "--";
    }

    function formatDateTime(timestamp) {
        return timestamp
            ? new Date(timestamp).toLocaleString()
            : "--";
    }

    function formatMonth(date) {
        return [
            date.getFullYear(),
            String(date.getMonth() + 1).padStart(2, "0")
        ].join("-");
    }

    function addMonths(date, months) {
        const result = new Date(date);

        result.setDate(1);
        result.setMonth(result.getMonth() + months);

        return result;
    }

    function getPreviousMonth(month) {
        if (!/^\d{4}-\d{2}$/.test(month || "")) {
            return null;
        }

        const [year, monthNumber] = month
            .split("-")
            .map(Number);

        return formatMonth(
            new Date(year, monthNumber - 2, 1)
        );
    }

    function getMonthDateRange(month) {
        if (!/^\d{4}-\d{2}$/.test(month || "")) {
            throw new Error(`无效月份：${month}`);
        }

        const [year, monthNumber] = month
            .split("-")
            .map(Number);

        const lastDay = new Date(
            year,
            monthNumber,
            0
        ).getDate();

        return {
            startDate:
                `${year}-${String(monthNumber).padStart(2, "0")}-01`,

            endDate:
                `${year}-${String(monthNumber).padStart(2, "0")}-${String(
                    lastDay
                ).padStart(2, "0")}`
        };
    }

    function getRandomDelay() {
        let interval = state.settings?.refreshIntervalSeconds * 1000;
        if (!interval || interval < 1000) interval = 5000;
        // add a small random jitter (0-200ms) so it's not exactly on the second
        return interval + Math.random() * 200;
    }

    function calculateChange(current, previous) {
        if (
            !Number.isFinite(current) ||
            !Number.isFinite(previous)
        ) {
            return null;
        }

        return current - previous;
    }

    function formatChange(value) {
        if (!Number.isFinite(value)) {
            return "上月无数据";
        }

        if (value > 0) {
            return `↑+${value}`;
        }

        if (value < 0) {
            return `↓${value}`;
        }

        return "—";
    }

    function getEmployeeExclusion(feedbackBy) {
        const employeeNumber =
            normalizeEmployeeNumber(feedbackBy);

        const prefix =
            state.settings.excludedEmployeePrefixes.find(item =>
                employeeNumber.startsWith(item)
            );

        if (!prefix) {
            return {
                excluded: false,
                prefix: null,
                reason: ""
            };
        }

        return {
            excluded: true,
            prefix,
            reason: `工号以 ${prefix} 开头`
        };
    }

    /* =========================================================
     * 3. 状态
     * ========================================================= */

    function createDetailState() {
        return {
            initialized: false,
            loading: false,

            lastError: null,
            lastFetchAt: null,
            lastScore: null,

            rows: [],
            rowMap: new Map(),
            audit: null,

            displayedRows: [],
            displayedAudit: null,
            displayedFetchAt: null,

            pendingViewUpdate: false,
            lastChanges: null
        };
    }

    const state = {
        running: true,

        refreshTimer: null,
        uiTimer: null,

        count: 0,
        isFetchingMain: false,

        currentDelay: 0,
        nextRefreshAt: 0,

        lastSuccessAt: null,
        lastError: null,

        allRows: [],
        latestRows: [],
        lastData: null,

        pipWindow: null,

        settings: loadSettings(),

        view: {
            mode: "monitor",
            restaurant: null,
            month: null,

            filter: "critical",
            sort: "impact",
            search: "",

            bodyScrollTop: 0,
            tableScrollTop: 0,
            tableScrollLeft: 0
        },

        detail: {
            xlsxReady:
                typeof window.XLSX !== "undefined",

            xlsxLoading: false,
            xlsxLoadError: null,

            SV: createDetailState(),
            CFC: createDetailState(),

            events: []
        }
    };

    window.__SATISFACTION_MONITOR__ = state;

    /* =========================================================
     * 4. 主满意度接口
     * ========================================================= */

    function getMainRequestBody() {
        const now = new Date();

        return {
            regionCode: "",
            countryAlphaCode: "",
            cityAlphaCode: "",
            canteenCode: "",

            publicStartMonth: formatMonth(
                addMonths(
                    now,
                    -(CONFIG.queryMonths - 1)
                )
            ),

            publicEndMonth: formatMonth(now)
        };
    }

    async function fetchPage(pageNumber) {
        const url =
            `${CONFIG.listApiBase}/${CONFIG.pageSize}/${pageNumber}`;

        const response = await fetch(url, {
            headers: {
                accept: "application/json, text/plain, */*",
                "content-type": "application/json"
            },

            referrer:
                "https://w3.huawei.com/iadmin/catering/",

            body: JSON.stringify(
                getMainRequestBody()
            ),

            method: "POST",
            mode: "cors",
            credentials: "include"
        });

        if (!response.ok) {
            throw new Error(
                `满意度接口请求失败：HTTP ${response.status}`
            );
        }

        const json = await response.json();

        if (json.code !== "success") {
            throw new Error(
                json.msg ||
                json.code ||
                "满意度接口调用失败"
            );
        }

        return json;
    }

    async function fetchAllRows() {
        const firstResponse = await fetchPage(1);

        const firstRows =
            firstResponse?.data?.result || [];

        const pageVO =
            firstResponse?.data?.pageVO || {};

        const totalRows =
            Number(pageVO.totalRows) ||
            firstRows.length;

        const pageSize =
            Number(pageVO.pageSize) ||
            CONFIG.pageSize;

        const totalPages = Math.max(
            1,
            Math.ceil(totalRows / pageSize)
        );

        if (totalPages <= 1) {
            return firstRows;
        }

        const requests = [];

        for (
            let page = 2;
            page <= totalPages;
            page++
        ) {
            requests.push(fetchPage(page));
        }

        const responses =
            await Promise.all(requests);

        return [
            ...firstRows,
            ...responses.flatMap(
                response =>
                    response?.data?.result || []
            )
        ];
    }

    function matchesRestaurant(row, keywords) {
        const fields = [
            row.canteenName,
            row.canteenNameCn,
            row.canteenNameEn,
            row.canteenCode
        ]
            .filter(Boolean)
            .map(normalizeText);

        return keywords.some(keyword => {
            const target =
                normalizeText(keyword);

            return fields.some(field =>
                field.includes(target)
            );
        });
    }

    function findRestaurantRow(
        rows,
        month,
        keywords
    ) {
        return (
            rows.find(
                row =>
                    row.publicMonth === month &&
                    matchesRestaurant(
                        row,
                        keywords
                    )
            ) || null
        );
    }

    function makeRestaurantData(
        name,
        currentRow,
        previousRow
    ) {
        if (!currentRow) {
            return {
                name,
                score: null,
                participants: null,
                longTerm: null,
                shortTerm: null,
                coverage: null,

                changes: {
                    participants: null,
                    longTerm: null,
                    shortTerm: null
                },

                currentRow: null,
                previousRow
            };
        }

        const participants =
            toNumber(currentRow.recycleNumber);

        const longTerm =
            toNumber(currentRow.longTermNumber);

        const shortTerm =
            toNumber(currentRow.shortTermNumber);

        const previousParticipants =
            toNumber(previousRow?.recycleNumber);

        const previousLongTerm =
            toNumber(previousRow?.longTermNumber);

        const previousShortTerm =
            toNumber(previousRow?.shortTermNumber);

        const coverageNumber =
            toNumber(currentRow.coverage);

        return {
            name,

            score:
                toNumber(currentRow.ratingGrade),

            participants,
            longTerm,
            shortTerm,

            coverage:
                currentRow.coverageString ||
                (
                    Number.isFinite(coverageNumber)
                        ? `${coverageNumber.toFixed(2)}%`
                        : null
                ),

            changes: {
                participants:
                    calculateChange(
                        participants,
                        previousParticipants
                    ),

                longTerm:
                    calculateChange(
                        longTerm,
                        previousLongTerm
                    ),

                shortTerm:
                    calculateChange(
                        shortTerm,
                        previousShortTerm
                    )
            },

            currentRow,
            previousRow
        };
    }

    function extractData(rows) {
        const months = [
            ...new Set(
                rows
                    .map(row => row.publicMonth)
                    .filter(month =>
                        /^\d{4}-\d{2}$/.test(
                            month || ""
                        )
                    )
            )
        ].sort();

        const latestMonth =
            months.at(-1);

        if (!latestMonth) {
            throw new Error(
                "没有识别到有效的 publicMonth"
            );
        }

        const previousMonth =
            getPreviousMonth(latestMonth);

        const result = {
            latestMonth,
            previousMonth,
            months,

            latestRows:
                rows.filter(
                    row =>
                        row.publicMonth === latestMonth
                ),

            SV: null,
            CFC: null
        };

        for (
            const [name, keywords]
            of Object.entries(
                CONFIG.restaurants
            )
        ) {
            result[name] =
                makeRestaurantData(
                    name,

                    findRestaurantRow(
                        rows,
                        latestMonth,
                        keywords
                    ),

                    findRestaurantRow(
                        rows,
                        previousMonth,
                        keywords
                    )
                );
        }

        return result;
    }

    /* =========================================================
     * 5. SheetJS
     * ========================================================= */

    function loadScript(url) {
        return new Promise((resolve, reject) => {
            const existing =
                document.querySelector(
                    `script[data-satisfaction-xlsx="${url}"]`
                );

            if (existing) {
                if (
                    typeof window.XLSX !== "undefined"
                ) {
                    resolve();
                    return;
                }

                existing.addEventListener(
                    "load",
                    resolve,
                    { once: true }
                );

                existing.addEventListener(
                    "error",
                    reject,
                    { once: true }
                );

                return;
            }

            const script =
                document.createElement("script");

            script.src = url;
            script.async = true;

            script.dataset.satisfactionXlsx =
                url;

            script.onload = resolve;

            script.onerror = () => {
                reject(
                    new Error(
                        `Excel 解析库加载失败：${url}`
                    )
                );
            };

            document.head.appendChild(script);
        });
    }

    async function ensureXLSX() {
        if (
            typeof window.XLSX !== "undefined"
        ) {
            state.detail.xlsxReady = true;
            return true;
        }

        if (state.detail.xlsxLoading) {
            for (
                let index = 0;
                index < 60;
                index++
            ) {
                await sleep(100);

                if (
                    typeof window.XLSX !== "undefined"
                ) {
                    state.detail.xlsxReady = true;
                    return true;
                }

                if (!state.detail.xlsxLoading) {
                    break;
                }
            }

            return (
                typeof window.XLSX !== "undefined"
            );
        }

        state.detail.xlsxLoading = true;
        state.detail.xlsxLoadError = null;

        try {
            for (
                const url
                of CONFIG.xlsxScriptUrls
            ) {
                try {
                    await loadScript(url);

                    if (
                        typeof window.XLSX !==
                        "undefined"
                    ) {
                        state.detail.xlsxReady = true;
                        return true;
                    }
                } catch (error) {
                    console.warn(error.message);
                }
            }

            throw new Error(
                "SheetJS 可能被公司页面 CSP 拦截"
            );
        } catch (error) {
            state.detail.xlsxReady = false;
            state.detail.xlsxLoadError = error;

            return false;
        } finally {
            state.detail.xlsxLoading = false;
        }
    }

    /* =========================================================
     * 6. 详表接口
     * ========================================================= */

    async function fetchDetailExcel(
        canteenCode,
        month
    ) {
        const {
            startDate,
            endDate
        } = getMonthDateRange(month);

        const response = await fetch(
            CONFIG.detailApi,
            {
                headers: {
                    accept:
                        "application/json, text/plain, */*",

                    "content-type":
                        "application/json"
                },

                referrer:
                    "https://w3.huawei.com/iadmin/catering/",

                body: JSON.stringify({
                    evaluationObjId:
                        canteenCode,

                    startDate,
                    endDate
                }),

                method: "POST",
                mode: "cors",
                credentials: "include"
            }
        );

        if (!response.ok) {
            throw new Error(
                `详表接口请求失败：HTTP ${response.status}`
            );
        }

        const arrayBuffer =
            await response.arrayBuffer();

        if (!arrayBuffer.byteLength) {
            throw new Error("详表文件为空");
        }

        return {
            arrayBuffer,
            size: arrayBuffer.byteLength
        };
    }

    function downloadArrayBuffer(
        arrayBuffer,
        filename
    ) {
        const blob = new Blob(
            [arrayBuffer],
            {
                type: "application/vnd.ms-excel"
            }
        );

        const url =
            URL.createObjectURL(blob);

        const anchor =
            document.createElement("a");

        anchor.href = url;
        anchor.download = filename;
        anchor.style.display = "none";

        document.body.appendChild(anchor);
        anchor.click();
        anchor.remove();

        setTimeout(
            () => URL.revokeObjectURL(url),
            5000
        );
    }

    /* =========================================================
     * 7. Excel 解析
     * ========================================================= */

    function findHeaderRowIndex(rows) {
        const maximum =
            Math.min(rows.length, 20);

        for (
            let index = 0;
            index < maximum;
            index++
        ) {
            const text =
                (rows[index] || [])
                    .map(normalizeHeader)
                    .join("|");

            if (
                /反馈人|Feedback By/i.test(text) &&
                /反馈时间|Feedback Time/i.test(text)
            ) {
                return index;
            }
        }

        return -1;
    }

    function findColumnIndex(
        headers,
        patterns
    ) {
        for (
            let index = 0;
            index < headers.length;
            index++
        ) {
            const header =
                normalizeHeader(headers[index]);

            if (
                patterns.some(pattern =>
                    pattern.test(header)
                )
            ) {
                return index;
            }
        }

        return -1;
    }

    function findAllColumnIndexes(
        headers,
        patterns
    ) {
        const indexes = [];

        for (
            let index = 0;
            index < headers.length;
            index++
        ) {
            const header =
                normalizeHeader(headers[index]);

            if (
                patterns.some(pattern =>
                    pattern.test(header)
                )
            ) {
                indexes.push(index);
            }
        }

        return indexes;
    }

    function makeDetailKey(row) {
        return [
            normalizeText(row.feedbackBy),
            normalizeText(row.feedbackTime),
            normalizeText(row.questionnaireName)
        ].join("||");
    }

    function makeFingerprint(row) {
        return JSON.stringify({
            feedbackType:
                row.feedbackType,

            scores:
                row.scores,

            comments:
                row.comments,

            openQuestion:
                row.openQuestion
        });
    }

    function applyExclusionToRow(row) {
        const exclusion =
            getEmployeeExclusion(
                row.feedbackBy
            );

        row.isExcluded =
            exclusion.excluded;

        row.excludedPrefix =
            exclusion.prefix;

        row.excludedReason =
            exclusion.reason;

        return row;
    }

    function parseWorksheetRows(
        worksheetRows,
        sheetName
    ) {
        const headerIndex =
            findHeaderRowIndex(
                worksheetRows
            );

        if (headerIndex < 0) {
            return [];
        }

        const headers =
            (worksheetRows[headerIndex] || [])
                .map(normalizeHeader);

        const questionnaireIndex =
            findColumnIndex(
                headers,
                [
                    /问卷名称/i,
                    /Questionnaire Name/i
                ]
            );

        const feedbackByIndex =
            findColumnIndex(
                headers,
                [
                    /^反馈人/i,
                    /Feedback By/i
                ]
            );

        const feedbackTypeIndex =
            findColumnIndex(
                headers,
                [
                    /反馈人类型/i,
                    /Feedback Type/i
                ]
            );

        const feedbackTimeIndex =
            findColumnIndex(
                headers,
                [
                    /反馈时间/i,
                    /Feedback Time/i
                ]
            );

        const patterns = {
            safety: [
                /^安全-食品安全$/i,
                /食品安全/i
            ],

            service: [
                /^服务-供餐服务$/i,
                /供餐服务/i
            ],

            activity: [
                /^活动-活动$/i
            ],

            environment: [
                /^环境-餐厅餐具$/i,
                /餐厅餐具/i
            ],

            dish: [
                /^菜品-出品$/i,
                /菜品-出品/i
            ]
        };

        const dimensionIndexes = {};

        for (
            const [dimension, dimensionPatterns]
            of Object.entries(patterns)
        ) {
            dimensionIndexes[dimension] =
                findAllColumnIndexes(
                    headers,
                    dimensionPatterns
                );
        }

        const openQuestionIndex =
            findColumnIndex(
                headers,
                [
                    /^问答-/i,
                    /Open-ended/i,
                    /您有什么想吃的/i
                ]
            );

        if (
            feedbackByIndex < 0 ||
            feedbackTimeIndex < 0
        ) {
            return [];
        }

        const parsedRows = [];

        for (
            let rowIndex = headerIndex + 1;
            rowIndex < worksheetRows.length;
            rowIndex++
        ) {
            const source =
                worksheetRows[rowIndex] || [];

            const feedbackBy =
                cleanCell(
                    source[feedbackByIndex]
                );

            const feedbackTime =
                cleanCell(
                    source[feedbackTimeIndex]
                );

            if (!feedbackBy && !feedbackTime) {
                continue;
            }

            const getScore =
                dimension => {
                    const index =
                        dimensionIndexes[
                        dimension
                        ]?.[0];

                    return Number.isInteger(index)
                        ? toNumber(source[index])
                        : null;
                };

            const getComment =
                dimension => {
                    const index =
                        dimensionIndexes[
                        dimension
                        ]?.[2];

                    return Number.isInteger(index)
                        ? cleanCell(source[index])
                        : "";
                };

            const scores = {
                safety:
                    getScore("safety"),

                service:
                    getScore("service"),

                activity:
                    getScore("activity"),

                environment:
                    getScore("environment"),

                dish:
                    getScore("dish")
            };

            const scoreArray =
                Object.values(scores);

            const numericScores =
                scoreArray.filter(
                    Number.isFinite
                );

            const validScores =
                numericScores.filter(
                    score =>
                        score >= 0 &&
                        score <= 5
                );

            const invalidScores =
                numericScores.filter(
                    score =>
                        score < 0 ||
                        score > 5
                );

            const sum =
                validScores.reduce(
                    (total, score) =>
                        total + score,
                    0
                );

            const validScoreCount =
                validScores.length;

            const maximum =
                validScoreCount * 5;

            const average =
                validScoreCount
                    ? sum / validScoreCount
                    : null;

            const isComplete =
                validScoreCount === 5;

            const isPerfect =
                isComplete &&
                validScores.every(
                    score => score === 5
                );

            const row = {
                sheetName,

                questionnaireName:
                    questionnaireIndex >= 0
                        ? cleanCell(
                            source[
                            questionnaireIndex
                            ]
                        )
                        : "",

                feedbackBy,

                feedbackType:
                    feedbackTypeIndex >= 0
                        ? cleanCell(
                            source[
                            feedbackTypeIndex
                            ]
                        )
                        : "",

                feedbackTime,

                scores,
                scoreArray,
                numericScores,

                validScoreCount,

                invalidScoreCount:
                    invalidScores.length,

                hasInvalid:
                    invalidScores.length > 0,

                hasMissing:
                    validScoreCount < 5,

                hasCriticalScore:
                    numericScores.some(score => score <= state.settings.criticalThreshold),

                hasSecondaryScore:
                    numericScores.some(score => score < state.settings.secondaryThreshold && score > state.settings.criticalThreshold),

                isComplete,
                isPerfect,

                sum,
                maximum,
                average,

                loss:
                    maximum - sum,

                comments: {
                    safety:
                        getComment("safety"),

                    service:
                        getComment("service"),

                    activity:
                        getComment("activity"),

                    environment:
                        getComment("environment"),

                    dish:
                        getComment("dish")
                },

                openQuestion:
                    openQuestionIndex >= 0
                        ? cleanCell(
                            source[
                            openQuestionIndex
                            ]
                        )
                        : "",

                excelRow:
                    rowIndex + 1
            };

            applyExclusionToRow(row);

            row.key =
                makeDetailKey(row);

            row.fingerprint =
                makeFingerprint(row);

            parsedRows.push(row);
        }

        return parsedRows;
    }

    function parseDetailWorkbook(
        arrayBuffer
    ) {
        if (
            typeof window.XLSX === "undefined"
        ) {
            throw new Error(
                "Excel 解析库尚未加载"
            );
        }

        const workbook =
            window.XLSX.read(
                arrayBuffer,
                {
                    type: "array",
                    raw: false,
                    cellDates: false
                }
            );

        const rows = [];

        for (
            const sheetName
            of workbook.SheetNames
        ) {
            const worksheet =
                workbook.Sheets[sheetName];

            const matrix =
                window.XLSX.utils
                    .sheet_to_json(
                        worksheet,
                        {
                            header: 1,
                            defval: "",
                            raw: false
                        }
                    );

            rows.push(
                ...parseWorksheetRows(
                    matrix,
                    sheetName
                )
            );
        }

        return rows;
    }

    /* =========================================================
     * 8. 复核计算
     * ========================================================= */

    function calculateAudit(
        rows,
        systemScore
    ) {
        rows.forEach(
            applyExclusionToRow
        );

        const excludedRows =
            rows.filter(
                row => row.isExcluded
            );

        const includedRows =
            rows.filter(
                row => !row.isExcluded
            );

        const validRows =
            includedRows.filter(
                row =>
                    row.validScoreCount > 0 &&
                    !row.hasInvalid
            );

        const perfectRows =
            validRows.filter(
                row => row.isPerfect
            );

        const criticalRows =
            validRows.filter(
                row => !row.isPerfect && row.hasCriticalScore
            );

        const secondaryRows =
            validRows.filter(
                row => !row.isPerfect && !row.hasCriticalScore && row.hasSecondaryScore
            );

        const totalActualScore =
            validRows.reduce(
                (total, row) =>
                    total + row.sum,
                0
            );

        const totalValidItems =
            validRows.reduce(
                (total, row) =>
                    total +
                    row.validScoreCount,
                0
            );

        const totalMaximumScore =
            totalValidItems * 5;

        let gapToTarget = 0;
        const avgMax = validRows.length > 0 ? (totalMaximumScore / validRows.length) : 25;

        if (totalMaximumScore > 0 && totalActualScore / totalMaximumScore < (state.settings.targetScore / 100)) {
            const targetRatio = state.settings.targetScore / 100;
            gapToTarget = Math.ceil((targetRatio * totalMaximumScore - totalActualScore) / ((1 - targetRatio) * avgMax));
        }

        const itemWeighted =
            totalMaximumScore > 0
                ? (
                    totalActualScore /
                    totalMaximumScore
                ) * 100
                : null;

        const personPercentages =
            validRows
                .map(row =>
                    row.maximum > 0
                        ? (
                            row.sum /
                            row.maximum
                        ) * 100
                        : null
                )
                .filter(Number.isFinite);

        const personAverage =
            personPercentages.length
                ? personPercentages.reduce(
                    (total, value) =>
                        total + value,
                    0
                ) /
                personPercentages.length
                : null;

        const dimensions = [
            "safety",
            "service",
            "activity",
            "environment",
            "dish"
        ];

        const dimensionStats = {};

        for (
            const dimension
            of dimensions
        ) {
            const values =
                validRows
                    .map(
                        row =>
                            row.scores[dimension]
                    )
                    .filter(
                        value =>
                            Number.isFinite(value) &&
                            value >= 1 &&
                            value <= 5
                    );

            const sum =
                values.reduce(
                    (total, value) =>
                        total + value,
                    0
                );

            dimensionStats[dimension] = {
                count: values.length,
                sum,

                average:
                    values.length
                        ? sum / values.length
                        : null
            };
        }

        const dimensionPercentages =
            Object.values(
                dimensionStats
            )
                .map(stat =>
                    Number.isFinite(
                        stat.average
                    )
                        ? (
                            stat.average /
                            5
                        ) * 100
                        : null
                )
                .filter(Number.isFinite);

        const dimensionAverage =
            dimensionPercentages.length
                ? dimensionPercentages.reduce(
                    (total, value) =>
                        total + value,
                    0
                ) /
                dimensionPercentages.length
                : null;

        const methods = [
            {
                key: "itemWeighted",
                name:
                    "有效评分项整体加权",
                value:
                    itemWeighted
            },

            {
                key: "personAverage",
                name:
                    "每人折算后再平均",
                value:
                    personAverage
            },

            {
                key: "dimensionAverage",
                name:
                    "五个维度等权平均",
                value:
                    dimensionAverage
            }
        ].map(method => ({
            ...method,

            rounded:
                round(
                    method.value,
                    2
                ),

            difference:
                (
                    Number.isFinite(
                        method.value
                    ) &&
                    Number.isFinite(
                        systemScore
                    )
                )
                    ? Math.abs(
                        round(
                            method.value,
                            2
                        ) -
                        systemScore
                    )
                    : null
        }));

        const closestMethod =
            methods
                .filter(method =>
                    Number.isFinite(
                        method.difference
                    )
                )
                .sort(
                    (a, b) =>
                        a.difference -
                        b.difference
                )[0] || null;

        const reviewedScore =
            closestMethod?.rounded ??
            round(itemWeighted, 2);

        const difference =
            (
                Number.isFinite(
                    reviewedScore
                ) &&
                Number.isFinite(
                    systemScore
                )
            )
                ? round(
                    reviewedScore -
                    systemScore,
                    4
                )
                : null;

        let status = "无法判断";

        if (Number.isFinite(difference)) {
            if (
                Math.abs(difference) <
                0.005
            ) {
                status = "一致";
            } else if (
                Math.abs(difference) <=
                0.02
            ) {
                status = "基本一致";
            } else {
                status = "不一致";
            }
        }

        /*
         * 只有计入复核的记录才计算影响。
         */
        for (const row of rows) {
            row.impact =
                (
                    !row.isExcluded &&
                    totalMaximumScore > 0
                )
                    ? (
                        row.loss /
                        totalMaximumScore
                    ) * 100
                    : null;
        }

        return {
            systemScore,
            reviewedScore,
            difference,
            status,

            methods,
            closestMethod,

            originalRowCount:
                rows.length,

            excludedRowCount:
                excludedRows.length,

            includedRowCount:
                includedRows.length,

            validQuestionnaires:
                validRows.length,

            perfectCount:
                perfectRows.length,

            criticalCount:
                criticalRows.length,

            secondaryCount:
                secondaryRows.length,

            totalActualScore,
            totalValidItems,
            totalMaximumScore,

            gapToTarget,

            itemWeighted,
            personAverage,
            dimensionAverage,

            dimensionStats,

            excludedRows,

            excludedPrefixes:
                state.settings
                    .excludedEmployeePrefixes
                    .slice()
        };
    }

    function recalculateAllAudits() {
        for (
            const name
            of ["SV", "CFC"]
        ) {
            const detailState =
                state.detail[name];

            if (!detailState.rows.length) {
                continue;
            }

            detailState.rows.forEach(row => {
                const numScores = row.numericScores || row.scoreArray?.filter(Number.isFinite);
                if (numScores) {
                    row.hasCriticalScore = numScores.some(score => score <= state.settings.criticalThreshold);
                    row.hasSecondaryScore = numScores.some(score => score < state.settings.secondaryThreshold && score > state.settings.criticalThreshold);
                }
                applyExclusionToRow(row);
            });

            detailState.audit =
                calculateAudit(
                    detailState.rows,
                    state.lastData?.[name]?.score
                );

            detailState.displayedRows.forEach(row => {
                const numScores = row.numericScores || row.scoreArray?.filter(Number.isFinite);
                if (numScores) {
                    row.hasCriticalScore = numScores.some(score => score <= state.settings.criticalThreshold);
                    row.hasSecondaryScore = numScores.some(score => score < state.settings.secondaryThreshold && score > state.settings.criticalThreshold);
                }
                applyExclusionToRow(row);
            });

            if (
                detailState.displayedRows.length
            ) {
                detailState.displayedAudit =
                    calculateAudit(
                        detailState.displayedRows,
                        detailState.displayedAudit
                            ?.systemScore ??
                        state.lastData?.[name]?.score
                    );
            }
        }
    }

    /* =========================================================
     * 9. 详表变化
     * ========================================================= */

    function buildDetailMap(rows) {
        const map = new Map();

        for (const row of rows) {
            map.set(row.key, row);
        }

        return map;
    }

    function compareDetailMaps(
        previousMap,
        currentMap
    ) {
        const added = [];
        const changed = [];
        const removed = [];

        for (
            const [key, currentRow]
            of currentMap.entries()
        ) {
            const previousRow =
                previousMap.get(key);

            if (!previousRow) {
                added.push(currentRow);
            } else if (
                previousRow.fingerprint !==
                currentRow.fingerprint
            ) {
                changed.push({
                    before: previousRow,
                    after: currentRow
                });
            }
        }

        for (
            const [key, previousRow]
            of previousMap.entries()
        ) {
            if (!currentMap.has(key)) {
                removed.push(previousRow);
            }
        }

        return {
            added,
            changed,
            removed,

            totalChanges:
                added.length +
                changed.length +
                removed.length
        };
    }

    function addDetailEvent(event) {
        state.detail.events.unshift(event);

        if (
            state.detail.events.length >
            CONFIG.maxStoredEvents
        ) {
            state.detail.events.length =
                CONFIG.maxStoredEvents;
        }
    }

    /* =========================================================
     * 10. 获取及更新详表
     * ========================================================= */

    async function refreshRestaurantDetail(
        restaurantName,
        restaurantData,
        reason,
        previousScore,
        options = {}
    ) {
        const {
            applyImmediately = false,
            userRequested = false
        } = options;

        const detailState =
            state.detail[restaurantName];

        if (!restaurantData?.currentRow) {
            detailState.lastError =
                new Error(
                    `${restaurantName} 没有当前月份记录`
                );

            updateDetailStatusOnly();
            return;
        }

        if (detailState.loading) {
            return;
        }

        const canteenCode =
            restaurantData.currentRow
                .canteenCode;

        const month =
            state.view.month || state.lastData?.latestMonth;

        if (!canteenCode || !month) {
            detailState.lastError =
                new Error(
                    `${restaurantName} 缺少餐厅编码或月份`
                );

            updateDetailStatusOnly();
            return;
        }

        detailState.loading = true;
        detailState.lastError = null;

        updateDetailStatusOnly();

        if (
            state.view.mode ===
            "monitor"
        ) {
            updateMonitorView();
        }

        try {
            const excel =
                await fetchDetailExcel(
                    canteenCode,
                    month
                );

            const xlsxReady =
                await ensureXLSX();

            if (!xlsxReady) {
                if (
                    CONFIG.autoDownloadWhenParseFails
                ) {
                    downloadArrayBuffer(
                        excel.arrayBuffer,
                        `${restaurantName}_${month}_满意度详表.xls`
                    );
                }

                throw new Error(
                    "Excel 解析库加载失败，详表已下载但无法自动分析"
                );
            }

            const rows =
                parseDetailWorkbook(
                    excel.arrayBuffer
                );

            const currentMap =
                buildDetailMap(rows);

            const wasInitialized =
                detailState.initialized;

            const changes =
                wasInitialized
                    ? compareDetailMaps(
                        detailState.rowMap,
                        currentMap
                    )
                    : {
                        added: [],
                        changed: [],
                        removed: [],
                        totalChanges: 0
                    };

            const audit =
                calculateAudit(
                    rows,
                    restaurantData.score
                );

            detailState.rows = rows;
            detailState.rowMap = currentMap;
            detailState.audit = audit;
            detailState.initialized = true;
            detailState.lastFetchAt = Date.now();
            detailState.lastScore =
                restaurantData.score;
            detailState.lastError = null;

            detailState.lastChanges = {
                reason,
                time: Date.now(),
                scoreBefore: previousScore,
                scoreAfter:
                    restaurantData.score,
                ...changes
            };

            if (
                !detailState.displayedRows.length ||
                applyImmediately
            ) {
                detailState.displayedRows =
                    rows.slice();

                detailState.displayedAudit =
                    audit;

                detailState.displayedFetchAt =
                    detailState.lastFetchAt;

                detailState.pendingViewUpdate =
                    false;
            } else {
                const displayedScore =
                    detailState.displayedAudit
                        ?.systemScore;

                const scoreChanged =
                    Number.isFinite(displayedScore) &&
                    Number.isFinite(
                        restaurantData.score
                    ) &&
                    displayedScore !==
                    restaurantData.score;

                if (
                    scoreChanged ||
                    changes.totalChanges > 0
                ) {
                    detailState.pendingViewUpdate =
                        true;
                }
            }

            if (!wasInitialized) {
                addDetailEvent({
                    restaurant: restaurantName,
                    type: "initial",
                    time: Date.now(),
                    totalRows: rows.length,
                    message:
                        `${restaurantName} 已建立 ${rows.length} 条反馈快照`
                });
            } else {
                addDetailEvent({
                    restaurant: restaurantName,
                    type:
                        changes.totalChanges
                            ? "changes"
                            : "updated",
                    time: Date.now(),
                    scoreBefore: previousScore,
                    scoreAfter:
                        restaurantData.score,
                    ...changes
                });
            }

            if (userRequested) {
                console.log(
                    `${restaurantName} 详表刷新完成，共 ${rows.length} 条。`
                );
            }
        } catch (error) {
            detailState.lastError = error;

            addDetailEvent({
                restaurant: restaurantName,
                type: "error",
                time: Date.now(),
                message: error.message
            });

            console.error(
                `${restaurantName} 详表处理失败：`,
                error
            );
        } finally {
            detailState.loading = false;

            updateDetailStatusOnly();

            if (
                state.view.mode ===
                "monitor"
            ) {
                updateMonitorView();
            }
        }
    }

    async function handleAutomaticDetailRefresh(
        previousData,
        currentData
    ) {
        const tasks = [];

        for (
            const name
            of ["SV", "CFC"]
        ) {
            const detailState =
                state.detail[name];

            const currentRestaurant =
                currentData[name];

            const previousScore =
                previousData?.[name]?.score;

            const currentScore =
                currentRestaurant?.score;

            const firstRun =
                !detailState.initialized;

            const scoreChanged =
                detailState.initialized &&
                Number.isFinite(currentScore) &&
                Number.isFinite(previousScore) &&
                currentScore !== previousScore;

            if (firstRun || scoreChanged) {
                tasks.push(
                    refreshRestaurantDetail(
                        name,
                        currentRestaurant,
                        firstRun
                            ? "initial"
                            : "score_changed",
                        previousScore,
                        {
                            applyImmediately: firstRun,
                            userRequested: false
                        }
                    )
                );
            }
        }

        if (tasks.length) {
            await Promise.allSettled(tasks);
        }
    }

    /* =========================================================
     * 11. PiP 窗口尺寸
     * ========================================================= */

    function resizeFloatWindow(
        mode,
        sourceDocument = null
    ) {
        /*
         * 优先使用实际产生点击事件的 PiP document。
         */
        const pipWindow =
            sourceDocument?.defaultView ||
            state.pipWindow ||
            documentPictureInPicture.window;

        if (!pipWindow || pipWindow.closed) {
            return false;
        }

        try {
            let targetWidth, targetHeight;
            if (mode === "detail") {
                const screenObject =
                    pipWindow.screen ||
                    window.screen ||
                    screen;

                const availableWidth =
                    window.innerWidth ||
                    screenObject?.availWidth ||
                    1200;

                const availableHeight =
                    window.innerHeight ||
                    screenObject?.availHeight ||
                    800;

                targetWidth = Math.min(
                    CONFIG.detailWindow.width,
                    Math.max(
                        760,
                        availableWidth - 80
                    )
                );

                targetHeight = Math.min(
                    CONFIG.detailWindow.height,
                    Math.max(
                        580,
                        availableHeight - 100
                    )
                );

                targetHeight = Math.min(targetHeight, Math.max(300, availableHeight - 40));
            } else {
                targetWidth = CONFIG.monitorWindow.width;
                targetHeight = CONFIG.monitorWindow.height;
            }

            if (state.pipWindow === pipWindow) {
                const iframe = document.getElementById('satisfaction-float-iframe');
                if (iframe) {
                    iframe.style.width = targetWidth + 'px';
                    iframe.style.height = targetHeight + 'px';

                    // Adjust close button position
                    const closeBtn = document.getElementById('satisfaction-float-close');
                    if (closeBtn) {
                        closeBtn.style.bottom = (20 + targetHeight - 12) + 'px';
                    }
                }
            } else {
                pipWindow.resizeTo(targetWidth, targetHeight);
            }

            return true;
        } catch (error) {
            console.warn(
                `浮窗切换到${mode === "detail"
                    ? "详情"
                    : "监控"
                }尺寸失败：`,
                error
            );

            return false;
        }
    }

