    function openSettingsDialog() {
        const doc =
            state.pipWindow?.document;

        if (!doc) {
            return;
        }

        doc
            .getElementById(
                "settingsOverlay"
            )
            ?.remove();

        const overlay =
            doc.createElement("div");

        overlay.id = "settingsOverlay";

        overlay.innerHTML = `
      <div class="settings-backdrop">
        <div class="settings-dialog">
