    function updateMonitorCard(
        prefix,
        restaurant
    ) {
        const doc =
            state.pipWindow?.document;

        if (!doc) {
            return;
        }

        const card =
            doc.getElementById(
                `${prefix}Card`
            );

        const score =
            restaurant?.score;

        card?.classList.remove(
            "pass",
            "fail"
        );

        if (Number.isFinite(score)) {
            card?.classList.add(
                score >= state.settings.targetScore
                    ? "pass"
                    : "fail"
            );
        }

        const scoreElement =
            doc.getElementById(
                `${prefix}Score`
            );

        const statusElement =
            doc.getElementById(
                `${prefix}Status`
            );

        if (scoreElement) {
            scoreElement.textContent =
                formatScore(score);
        }

        if (statusElement) {
            statusElement.textContent =
                !Number.isFinite(score)
                    ? "暂无数据"
                    : score >= state.settings.targetScore
                        ? "达标"
                        : `未达标，差 ${(
                            state.settings.targetScore -
                            score
                        ).toFixed(2)} 分`;
        }

        const values = {
            Participants:
                restaurant?.participants,

            LongTerm:
                restaurant?.longTerm,

            ShortTerm:
                restaurant?.shortTerm
        };

        for (
            const [suffix, value]
            of Object.entries(values)
        ) {
            const element =
                doc.getElementById(
                    `${prefix}${suffix}`
                );

            if (element) {
                element.textContent =
                    formatInteger(value);
            }
        }

        const coverage =
            doc.getElementById(
                `${prefix}Coverage`
            );

        if (coverage) {
            coverage.textContent =
                restaurant?.coverage ||
                "--";
        }

        const changes = {
            ParticipantsChange:
                restaurant?.changes
                    ?.participants,

            LongTermChange:
                restaurant?.changes
                    ?.longTerm,

            ShortTermChange:
                restaurant?.changes
                    ?.shortTerm
        };

        for (
            const [suffix, value]
            of Object.entries(changes)
        ) {
            const element =
                doc.getElementById(
                    `${prefix}${suffix}`
                );

            if (!element) {
                continue;
            }

            element.textContent =
                formatChange(value);

            element.className =
                !Number.isFinite(value)
                    ? "muted"
                    : value > 0
                        ? "good"
                        : value < 0
                            ? "bad"
                            : "muted";
        }
    }

    function updateLatestChangePanel() {
        const doc =
            state.pipWindow?.document;

        if (!doc) {
            return;
        }

        const badge =
            doc.getElementById(
                "detailStateBadge"
            );

        const content =
            doc.getElementById(
                "latestChangeContent"
            );

        if (!badge || !content) {
            return;
        }

        const loading =
            ["SV", "CFC"].filter(
                name =>
                    state.detail[name].loading
            );

        if (loading.length) {
            badge.textContent =
                `${loading.join("/")} 获取中`;

            content.textContent =
                "正在后台获取本月评分详表并复核……";

            return;
        }

        const latestEvent =
            state.detail.events[0];

        if (!latestEvent) {
            const initialized =
                ["SV", "CFC"].filter(
                    name =>
                        state.detail[name]
                            .initialized
                ).length;

            badge.textContent =
                initialized
                    ? `已初始化 ${initialized}/2`
                    : "等待详表";

            content.textContent =
                initialized
                    ? "反馈快照已建立，分数变化时将自动重新分析。"
                    : "首次获取分数后将自动建立反馈快照。";

            return;
        }

        if (
            latestEvent.type ===
            "error"
        ) {
            badge.textContent =
                `${latestEvent.restaurant} 失败`;

            content.innerHTML =
                `<span class="bad">${escapeHtml(
                    latestEvent.message
                )}</span>`;

            return;
        }

        if (
            latestEvent.type ===
            "initial"
        ) {
            badge.textContent =
                `${latestEvent.restaurant} 已初始化`;

            content.innerHTML =
                `${escapeHtml(
                    latestEvent.restaurant
                )} 已建立 <strong>${latestEvent.totalRows}</strong> 条反馈快照`;

            return;
        }

        if (
            latestEvent.type ===
            "changes"
        ) {
            badge.textContent =
                `${latestEvent.restaurant} 变化 ${latestEvent.totalChanges}`;

            content.innerHTML = `
        <strong>
          ${escapeHtml(
                latestEvent.restaurant
            )}
        </strong>
        分数
        ${formatScore(
                latestEvent.scoreBefore
            )}
        →
        ${formatScore(
                latestEvent.scoreAfter
            )}，
        新增 ${latestEvent.added.length}，
        修改 ${latestEvent.changed.length}，
        删除 ${latestEvent.removed.length}
      `;

            return;
        }

        badge.textContent =
            `${latestEvent.restaurant} 已更新`;

        content.textContent =
            "详表已重新获取，未识别到记录级变化。";
    }

    function updateMonitorRefreshUi() {
        if (
            state.view.mode !==
            "monitor"
        ) {
            return;
        }

        const doc =
            state.pipWindow?.document;

        if (!doc) {
            return;
        }

        const countdown =
            doc.getElementById(
                "countdownText"
            );

        const progress =
            doc.getElementById(
                "progressBar"
            );

        const status =
            doc.getElementById(
                "refreshStatus"
            );

        const liveDot =
            doc.getElementById(
                "liveDot"
            );

        const liveText =
            doc.getElementById(
                "liveText"
            );

        const updateTime =
            doc.getElementById(
                "updateTime"
            );

        liveDot?.classList.remove(
            "fetching",
            "error"
        );

        if (state.isFetchingMain) {
            if (countdown) {
                countdown.textContent =
                    "正在刷新…";
            }

            if (status) {
                status.textContent =
                    "正在请求最新数据";
            }

            if (liveText) {
                liveText.textContent =
                    "正在获取数据";
            }

            liveDot?.classList.add(
                "fetching"
            );

            progress?.classList.add(
                "fetching"
            );

            return;
        }

        progress?.classList.remove(
            "fetching"
        );

        if (state.lastError) {
            if (liveText) {
                liveText.textContent =
                    "获取失败";
            }

            liveDot?.classList.add(
                "error"
            );
        } else if (liveText) {
            liveText.textContent =
                "监控运行中";
        }

        const remaining =
            state.nextRefreshAt
                ? Math.max(
                    0,
                    state.nextRefreshAt -
                    Date.now()
                )
                : 0;

        if (countdown) {
            countdown.textContent =
                state.nextRefreshAt
                    ? `${(
                        remaining /
                        1000
                    ).toFixed(1)} 秒后刷新`
                    : "准备刷新";
        }

        if (progress) {
            const ratio =
                state.currentDelay > 0
                    ? Math.max(
                        0,
                        Math.min(
                            1,
                            remaining /
                            state.currentDelay
                        )
                    )
                    : 0;

            progress.style.transform =
                `scaleX(${ratio})`;
        }

        if (status) {
            if (state.lastError) {
                status.textContent =
                    "上次获取失败，将自动重试";
            } else if (state.lastSuccessAt) {
                const seconds =
                    Math.floor(
                        (
                            Date.now() -
                            state.lastSuccessAt
                        ) /
                        1000
                    );

                status.textContent =
                    seconds <= 1
                        ? "刚刚获取成功"
                        : `${seconds} 秒前获取成功`;
            } else {
                status.textContent =
                    "等待首次获取";
            }
        }

        if (updateTime) {
            updateTime.textContent =
                state.lastSuccessAt
                    ? new Date(
                        state.lastSuccessAt
                    ).toLocaleTimeString()
                    : "--";
        }
    }

    function updateMonitorView() {
