            restaurantName
        ].displayedAudit;
    }

    function getFilteredDetailRows(
        restaurantName
    ) {
        let rows =
            getDisplayedRows(
                restaurantName
            ).slice();

        switch (state.view.filter) {
            case "included":
                rows =
                    rows.filter(
                        row => !row.isExcluded
                    );
                break;

            case "perfect":
                rows =
                    rows.filter(
                        row =>
                            !row.isExcluded &&
                            row.isPerfect
                    );
                break;

            case "critical":
                rows =
                    rows.filter(
                        row =>
                            !row.isExcluded &&
                            !row.isPerfect &&
                            row.hasCriticalScore &&
                            !row.hasInvalid &&
                            row.validScoreCount > 0
                    );
                break;

            case "secondary":
                rows =
                    rows.filter(
                        row =>
                            !row.isExcluded &&
                            !row.isPerfect &&
                            !row.hasCriticalScore &&
                            row.hasSecondaryScore &&
                            !row.hasInvalid &&
                            row.validScoreCount > 0
                    );
                break;

            case "excluded":
                rows =
                    rows.filter(
                        row => row.isExcluded
                    );
                break;

            default:
                break;
        }

        const keyword =
            normalizeText(
                state.view.search
            );

        if (keyword) {
            rows =
                rows.filter(row =>
                    [
                        row.feedbackBy,
                        row.feedbackType,
                        row.feedbackTime,
                        row.openQuestion,
                        row.excludedReason,

                        ...Object.values(
                            row.comments
                        )
                    ].some(value =>
                        normalizeText(value)
                            .includes(keyword)
                    )
                );
        }

        switch (state.view.sort) {
            case "time":
                rows.sort(
                    (a, b) =>
                        String(
                            b.feedbackTime
                        ).localeCompare(
                            String(
                                a.feedbackTime
                            )
                        )
                );
                break;

            case "averageAsc":
                rows.sort(
                    (a, b) =>
                        (
                            a.average ??
                            Infinity
                        ) -
                        (
                            b.average ??
                            Infinity
                        )
                );
                break;

            case "averageDesc":
                rows.sort(
                    (a, b) =>
                        (
                            b.average ??
                            -Infinity
                        ) -
                        (
                            a.average ??
                            -Infinity
                        )
                );
                break;

            default:
                rows.sort(
                    (a, b) =>
                        (
                            b.impact ?? 0
                        ) -
                        (
                            a.impact ?? 0
                        )
                );
                break;
        }

        return rows;
    }

    function getScoreCellClass(score) {
        if (!Number.isFinite(score)) {
            return "score-empty";
        }

        if (score === 5) {
            return "score-five";
        }

        if (
            score >= 1 &&
            score <= 5
        ) {
            return score <= 3
                ? "score-low"
                : "score-nonfive";
        }

        return "score-invalid";
    }

    function getRowComment(row) {
        return (
            row.openQuestion ||
            Object.values(
                row.comments
            )
                .filter(Boolean)
                .join("；")
        );
    }

    function renderDetailTableRows(
        restaurantName
    ) {
        const rows =
            getFilteredDetailRows(
                restaurantName
            );

        if (!rows.length) {
            return `
        <tr>
          <td
            colspan="13"
            class="empty-row"
          >
            当前筛选条件下没有数据
          </td>
        </tr>
      `;
        }

        return rows.map(row => {
            const scoreCells =
                [
                    row.scores.safety,
                    row.scores.service,
                    row.scores.activity,
                    row.scores.environment,
                    row.scores.dish
                ]
                    .map(
                        score => `
              <td
                class="${getScoreCellClass(
                            score
                        )}"
              >
                ${Number.isFinite(score)
                                ? score
                                : "-"
                            }
              </td>
            `
                    )
                    .join("");

            const rowClass =
                row.isExcluded
                    ? "excluded-row"
                    : row.hasInvalid ||
                        row.validScoreCount === 0
                        ? "abnormal-row"
                        : row.isPerfect
                            ? "perfect-row"
                            : "non-perfect-row";

            const percentage =
                row.maximum > 0
                    ? (
                        row.sum /
                        row.maximum
                    ) * 100
                    : null;

            return `
        <tr class="${rowClass}">
          <td>
            ${escapeHtml(
                row.feedbackBy
            )}
          </td>

          <td>
            ${escapeHtml(
                row.feedbackType
            )}
          </td>

          <td class="time-cell">
            ${escapeHtml(
                row.feedbackTime
            )}
          </td>

          ${scoreCells}

          <td class="mono">
            ${formatScore(
                row.average
            )}
          </td>

          <td class="mono">
            ${formatScore(
                percentage
            )}
          </td>

          <td class="mono impact-cell">
            ${row.isExcluded
                    ? "--"
                    : Number.isFinite(
                        row.impact
                    )
                        ? `-${row.impact.toFixed(
                            4
                        )}`
                        : "--"
                }
          </td>

          <td>
            ${row.isExcluded
                    ? `
                  <span class="excluded-tag">
                    已排除
                  </span>
                  ${escapeHtml(
                        row.excludedReason
                    )}
                `
                    : "计入复核"
                }
          </td>

          <td
            class="comment-cell"
            title="${escapeHtml(
                    getRowComment(row)
                )}"
          >
            ${escapeHtml(
                    getRowComment(row)
                )}
          </td>
        </tr>
      `;
        }).join("");
    }

