    function updateDetailStatusOnly() {
        if (
            state.view.mode !==
            "detail"
        ) {
            return;
        }

        const restaurantName =
            state.view.restaurant;

        const detailState =
            state.detail[
            restaurantName
            ];

        const doc =
            state.pipWindow?.document;

        if (!doc) {
            return;
        }

        const statusDot =
            doc.getElementById(
                "detailLiveDot"
            );

        const statusText =
            doc.getElementById(
                "detailLiveText"
            );

        const backgroundTime =
            doc.getElementById(
                "detailBackgroundTime"
            );

        const updateBanner =
            doc.getElementById(
                "detailUpdateBanner"
            );

        const updateBannerText =
            doc.getElementById(
                "detailUpdateText"
            );

        statusDot?.classList.remove(
            "fetching",
            "error"
        );

        if (detailState.loading) {
            statusDot?.classList.add(
                "fetching"
            );

            if (statusText) {
                statusText.textContent =
                    "后台正在获取最新详表";
            }
        } else if (
            detailState.lastError
        ) {
            statusDot?.classList.add(
                "error"
            );

            if (statusText) {
                statusText.textContent =
                    `后台更新失败：${detailState.lastError.message}`;
            }
        } else if (statusText) {
            statusText.textContent =
                "后台监控持续运行，不会自动刷新当前表格";
        }

        if (backgroundTime) {
            backgroundTime.textContent =
                detailState.lastFetchAt
                    ? `后台最新：${formatDateTime(
                        detailState.lastFetchAt
                    )}`
                    : "后台尚未获取";
        }

        if (updateBanner) {
            updateBanner.hidden =
                !detailState.pendingViewUpdate;
        }

        if (
            updateBannerText &&
            detailState.pendingViewUpdate
        ) {
            const changes =
                detailState.lastChanges;

            const summary = [];

            if (
                Number.isFinite(
                    changes?.scoreBefore
                ) &&
                Number.isFinite(
                    changes?.scoreAfter
                ) &&
                changes.scoreBefore !==
                changes.scoreAfter
            ) {
                summary.push(
                    `系统分数 ${formatScore(
                        changes.scoreBefore
                    )} → ${formatScore(
                        changes.scoreAfter
                    )}`
                );
            }

            if (changes?.totalChanges) {
                summary.push(
                    `新增 ${changes.added.length}、修改 ${changes.changed.length}、删除 ${changes.removed.length}`
                );
            }

            updateBannerText.textContent =
                summary.length
                    ? summary.join("｜")
                    : "后台已获取到新数据";
        }

        const liveSystemScore =
            doc.getElementById(
                "liveSystemScore"
            );

        if (liveSystemScore) {
            liveSystemScore.textContent =
                formatScore(
                    state.lastData?.[
                        restaurantName
                    ]?.score
                );
        }
    }

