        return audit.methods.map(method => {
            const isClosest =
                audit.closestMethod?.key ===
                method.key;

            return `
        <div class="method-row ${isClosest
                    ? "closest-method"
                    : ""
                }">
          <span>
            ${escapeHtml(
                    method.name
                )}
          </span>

          <strong class="mono">
            ${formatScore(
                    method.rounded
                )}
          </strong>

          <span class="mono method-diff">
            ${Number.isFinite(
                    method.difference
                )
                    ? `差 ${method.difference.toFixed(
                        2
                    )}`
                    : "--"
                }
          </span>

          ${isClosest
                    ? `
                <span class="method-tag">
                  最接近系统
                </span>
              `
                    : ""
                }
        </div>
      `;
        }).join("");
    }

