        const scrollTop =
            tableWrap?.scrollTop || 0;

        const scrollLeft =
            tableWrap?.scrollLeft || 0;

        body.innerHTML =
            renderDetailTableRows(
                restaurantName
            );

        if (tableWrap) {
            tableWrap.scrollTop =
                scrollTop;

            tableWrap.scrollLeft =
                scrollLeft;
        }
    }

    async function openDetailView(
        restaurantName,
        targetMonth = null
    ) {
        state.view.mode = "detail";
        state.view.restaurant = restaurantName;
        state.view.month = targetMonth || state.view.month || state.lastData?.latestMonth;

        state.view.filter =
            "critical";

        state.view.sort =
            "impact";

        state.view.search = "";
        state.view.bodyScrollTop = 0;
        state.view.tableScrollTop = 0;
        state.view.tableScrollLeft = 0;

        const detailState =
            state.detail[
            restaurantName
            ];

        const restaurant =
            state.lastData?.[
            restaurantName
            ];

        renderDetailView(
            restaurantName
        );

        if (
            !detailState.initialized &&
            !detailState.loading &&
            restaurant
        ) {
            await refreshRestaurantDetail(
                restaurantName,
                restaurant,
                "initial_open",
                detailState.lastScore,
                {
                    applyImmediately: true,
                    userRequested: true
                }
            );

            renderDetailView(
                restaurantName
            );
        }
    }

    /* =========================================================
