    async function openFloatWindow() {
        if (state.pipWindow && !state.pipWindow.closed) {
            return;
        }

        try {
            const existing = document.getElementById('satisfaction-float-iframe');
            if (existing) existing.remove();
            const existingBtn = document.getElementById('satisfaction-float-close');
            if (existingBtn) existingBtn.remove();

            const iframe = document.createElement('iframe');
            iframe.id = 'satisfaction-float-iframe';
            Object.assign(iframe.style, {
                position: 'fixed',
                bottom: '20px',
                right: '20px',
                width: CONFIG.monitorWindow.width + 'px',
                height: CONFIG.monitorWindow.height + 'px',
                border: '1px solid #ddd',
                boxShadow: '0 8px 24px rgba(0,0,0,0.15)',
                borderRadius: '8px',
                zIndex: '999999',
                backgroundColor: '#fff'
            });
            document.body.appendChild(iframe);

            const pipWindow = iframe.contentWindow;
            pipWindow.focus = () => {};
            Object.defineProperty(pipWindow, 'closed', {
                get: () => !document.body.contains(iframe)
            });

            state.pipWindow = pipWindow;
            window.__SATISFACTION_FLOAT_WINDOW__ = pipWindow;

            // Wait for iframe document to be accessible
            await new Promise(resolve => setTimeout(resolve, 50));

            renderMonitorView();

            if (state.uiTimer) {
                clearInterval(state.uiTimer);
            }

            state.uiTimer = setInterval(() => {
                if (state.view.mode === "monitor") {
                    updateMonitorRefreshUi();
                } else {
                    updateDetailStatusOnly();
                }
            }, 200);

            const closeBtn = document.createElement('div');
            closeBtn.id = 'satisfaction-float-close';
            closeBtn.innerHTML = '×';
            Object.assign(closeBtn.style, {
                position: 'fixed',
                bottom: (20 + CONFIG.monitorWindow.height - 12) + 'px',
                right: '12px',
                width: '24px',
                height: '24px',
                background: '#ff4d4f',
                color: '#fff',
                textAlign: 'center',
                lineHeight: '22px',
                borderRadius: '50%',
                cursor: 'pointer',
                zIndex: '1000000',
                fontSize: '16px',
                fontWeight: 'bold',
                boxShadow: '0 2px 8px rgba(0,0,0,0.2)'
            });

            const expandBtn = document.createElement('div');
            expandBtn.id = 'satisfaction-float-expand';
            expandBtn.innerHTML = '监控中';
            Object.assign(expandBtn.style, {
                position: 'fixed',
                bottom: '20px',
                right: '20px',
                width: '60px',
                height: '60px',
                background: '#1677ff',
                color: '#fff',
                textAlign: 'center',
                lineHeight: '60px',
                borderRadius: '50%',
                cursor: 'pointer',
                zIndex: '1000000',
                fontSize: '14px',
                fontWeight: 'bold',
                boxShadow: '0 4px 12px rgba(0,0,0,0.3)',
                display: 'none'
            });
            document.body.appendChild(expandBtn);

            const toggleMinimize = (minimized) => {
                if (minimized) {
                    iframe.style.display = 'none';
                    closeBtn.style.display = 'none';
                    expandBtn.style.display = 'block';
                } else {
                    iframe.style.display = 'block';
                    closeBtn.style.display = 'block';
                    expandBtn.style.display = 'none';
                }
            };
            expandBtn.onclick = () => toggleMinimize(false);

            closeBtn.onclick = () => {
                const dialogOverlay = document.createElement('div');
                Object.assign(dialogOverlay.style, {
                    position: 'fixed',
                    top: '0', left: '0', width: '100vw', height: '100vh',
                    background: 'rgba(0,0,0,0.5)',
                    zIndex: '2000000',
                    display: 'flex', alignItems: 'center', justifyContent: 'center'
                });
                const dialogBox = document.createElement('div');
                Object.assign(dialogBox.style, {
                    background: '#fff',
                    borderRadius: '8px',
                    padding: '24px',
                    width: '320px',
                    boxShadow: '0 8px 24px rgba(0,0,0,0.2)',
                    fontFamily: 'system-ui, -apple-system, sans-serif'
                });
                dialogBox.innerHTML = `
                    <h3 style="margin:0 0 12px 0; font-size:18px; color:#1f2937; font-weight:600;">停止满意度监控</h3>
                    <p style="font-size:14px; color:#4b5563; margin:0 0 20px 0; line-height:1.5;">您要彻底停止运行还是仅仅最小化悬浮窗？</p>
                    <div style="display:flex; justify-content:flex-end; gap:12px;">
                        <button id="dlg-min-btn" style="padding:8px 16px; border:1px solid #d1d5db; background:#fff; border-radius:6px; cursor:pointer; font-size:14px; font-weight:500; color:#374151; transition:all 0.2s;">最小化窗口</button>
                        <button id="dlg-stop-btn" style="padding:8px 16px; border:none; background:#ef4444; color:#fff; border-radius:6px; cursor:pointer; font-size:14px; font-weight:500; transition:all 0.2s;">彻底停止</button>
                    </div>
                `;
                dialogOverlay.appendChild(dialogBox);
                document.body.appendChild(dialogOverlay);

                const minBtn = dialogBox.querySelector('#dlg-min-btn');
                const stopBtn = dialogBox.querySelector('#dlg-stop-btn');

                minBtn.onmouseover = () => minBtn.style.background = '#f9fafb';
                minBtn.onmouseout = () => minBtn.style.background = '#fff';

                stopBtn.onmouseover = () => stopBtn.style.background = '#dc2626';
                stopBtn.onmouseout = () => stopBtn.style.background = '#ef4444';

                stopBtn.onclick = () => {
                    dialogOverlay.remove();
                    if (window.stopSatisfactionMonitor) {
                        window.stopSatisfactionMonitor();
                    }
                };
                minBtn.onclick = () => {
                    dialogOverlay.remove();
                    toggleMinimize(true);
                };
            };
            document.body.appendChild(closeBtn);

        } catch (error) {
            console.warn("浮窗打开失败：", error);
        }
    }

    /* =========================================================
     * 19. 主循环
     * ========================================================= */

    async function runOnce() {
        if (!state.running) {
            return;
        }

        state.isFetchingMain = true;
        state.nextRefreshAt = 0;

        if (
            state.view.mode ===
            "monitor"
        ) {
            updateMonitorView();
        } else {
            updateDetailStatusOnly();
        }

        const previousData =
            state.lastData;

        try {
            const rows =
                await fetchAllRows();

            const data =
                extractData(rows);

            state.count++;
            state.allRows = rows;
            state.latestRows =
                data.latestRows;
            state.lastData = data;
            state.lastError = null;
            state.lastSuccessAt =
                Date.now();

            await handleAutomaticDetailRefresh(
                previousData,
                data
            );
        } catch (error) {
            state.lastError = error;

            console.error(
                `[${new Date().toLocaleTimeString()}] 获取满意度失败：`,
                error
            );
        } finally {
            state.isFetchingMain = false;

            const nextDelay =
                getRandomDelay();

            state.currentDelay =
                nextDelay;

            state.nextRefreshAt =
                Date.now() +
                nextDelay;

            if (
                state.view.mode ===
                "monitor"
            ) {
                updateMonitorView();
            } else {
                updateDetailStatusOnly();
            }

            if (state.running) {
                state.refreshTimer =
                    setTimeout(
                        runOnce,
                        nextDelay
                    );
            }
        }
    }

    /* =========================================================
     * 20. 控制台命令
     * ========================================================= */

    window.openSatisfactionFloatWindow =
        openFloatWindow;

    window.closeSatisfactionFloatWindow =
        () => {
            if (
                state.pipWindow &&
                !state.pipWindow.closed
            ) {
                state.pipWindow.close();
            }
        };

    window.openSatisfactionSettings =
        openSettingsDialog;

    window.getSatisfactionSettings =
        () => ({
            excludedEmployeePrefixes:
                state.settings
                    .excludedEmployeePrefixes
                    .slice()
        });

    window.setSatisfactionExcludedPrefixes =
        prefixes => {
            const normalized =
                Array.isArray(prefixes)
                    ? normalizePrefixList(prefixes)
                    : parsePrefixText(prefixes);

            state.settings
                .excludedEmployeePrefixes =
                normalized;

            saveSettings();
            recalculateAllAudits();

            if (
                state.view.mode ===
                "detail"
            ) {
                renderDetailView(
                    state.view.restaurant,
                    {
                        preserveScroll: true
                    }
                );
            } else {
                updateMonitorView();
            }

            console.log(
                "排除前缀已更新：",
                normalized
            );

            return normalized;
        };

    window.resetSatisfactionSettings =
        () => {
            state.settings = {
                excludedEmployeePrefixes:
                    DEFAULT_SETTINGS
                        .excludedEmployeePrefixes
                        .slice()
            };

            saveSettings();
            recalculateAllAudits();

            if (
                state.view.mode ===
                "detail"
            ) {
                renderDetailView(
                    state.view.restaurant,
                    {
                        preserveScroll: true
                    }
                );
            } else {
                updateMonitorView();
            }

            console.log(
                "满意度复核设置已恢复默认"
            );
        };

    window.openSatisfactionDetail =
        restaurantName => {
            const name =
                String(
                    restaurantName || "SV"
                ).toUpperCase();

            if (
                !["SV", "CFC"].includes(name)
            ) {
                console.error(
                    "只能填写 SV 或 CFC"
                );
                return;
            }

            /*
             * Console 不一定具备用户激活，
             * 因此只切换内容，不能保证自动放大。
             */
            return openDetailView(name);
        };

    window.backToSatisfactionMonitor =
        () => {
            renderMonitorView();

            console.log(
                "已返回监控界面。通过详情页左上角按钮返回时会自动缩小。"
            );
        };

    window.refreshSatisfactionDetails =
        async restaurantName => {
            const names =
                restaurantName
                    ? [
                        String(
                            restaurantName
                        ).toUpperCase()
                    ]
                    : ["SV", "CFC"];

            for (const name of names) {
                if (
                    !["SV", "CFC"].includes(name)
                ) {
                    console.error(
                        "只能填写 SV 或 CFC"
                    );
                    continue;
                }

                const restaurant =
                    state.lastData?.[name];

                if (!restaurant) {
                    console.warn(
                        `${name} 暂无主接口数据`
                    );
                    continue;
                }

                await refreshRestaurantDetail(
                    name,
                    restaurant,
                    "manual_console",
                    state.detail[name].lastScore,
                    {
                        applyImmediately: false,
                        userRequested: true
                    }
                );
            }
        };

    window.applyLatestSatisfactionDetail =
        restaurantName => {
            const name =
                String(
                    restaurantName ||
                    state.view.restaurant ||
                    "SV"
                ).toUpperCase();

            const detailState =
                state.detail[name];

            if (!detailState) {
                console.error(
                    "只能填写 SV 或 CFC"
                );
                return;
            }

            detailState.displayedRows =
                detailState.rows.slice();

            detailState.displayedAudit =
                detailState.audit;

            detailState.displayedFetchAt =
                detailState.lastFetchAt;

            detailState.pendingViewUpdate =
                false;

            if (
                state.view.mode ===
                "detail" &&
                state.view.restaurant ===
                name
            ) {
                renderDetailView(
                    name,
                    {
                        preserveScroll: true
                    }
                );
            }
        };

    window.showSatisfactionAudit =
        restaurantName => {
            const name =
                String(
                    restaurantName || "SV"
                ).toUpperCase();

            const audit =
                state.detail[name]?.audit;

            if (!audit) {
                console.warn(
                    `${name} 暂无复核数据`
                );
                return;
            }

            console.log(
                `${name} 复核详情：`,
                audit
            );

            console.table(
                audit.methods.map(method => ({
                    计算口径:
                        method.name,

                    复核分数:
                        method.rounded,

                    与系统差异:
                        method.difference,

                    是否最接近:
                        audit.closestMethod
                            ?.key ===
                            method.key
                            ? "是"
                            : ""
                }))
            );

            console.table(
                audit.excludedRows.map(row => ({
                    反馈人:
                        row.feedbackBy,

                    类型:
                        row.feedbackType,

                    反馈时间:
                        row.feedbackTime,

                    排除原因:
                        row.excludedReason,

                    评分:
                        row.scoreArray
                            .map(value =>
                                Number.isFinite(value)
                                    ? value
                                    : "-"
                            )
                            .join(" / ")
                }))
            );

            return audit;
        };

    window.showCurrentSatisfactionDetails =
        restaurantName => {
            const name =
                String(
                    restaurantName || "SV"
                ).toUpperCase();

            const rows =
                state.detail[name]?.rows;

            if (!rows?.length) {
                console.warn(
                    `${name} 暂无详表数据`
                );
                return;
            }

            console.table(
                rows.map(row => ({
                    反馈人:
                        row.feedbackBy,

                    类型:
                        row.feedbackType,

                    反馈时间:
                        row.feedbackTime,

                    食品安全:
                        row.scores.safety,

                    供餐服务:
                        row.scores.service,

                    活动:
                        row.scores.activity,

                    餐具环境:
                        row.scores.environment,

                    菜品出品:
                        row.scores.dish,

                    平均分:
                        formatScore(
                            row.average
                        ),

                    是否全五分:
                        row.isPerfect
                            ? "是"
                            : "否",

                    是否排除:
                        row.isExcluded
                            ? "是"
                            : "否",

                    排除原因:
                        row.excludedReason,

                    拉低总满意度:
                        Number.isFinite(
                            row.impact
                        )
                            ? row.impact.toFixed(4)
                            : "--",

                    心愿美食:
                        row.openQuestion
                }))
            );

            return rows;
        };

    window.downloadSatisfactionDetails =
        async restaurantName => {
            const name =
                String(
                    restaurantName || "SV"
                ).toUpperCase();

            const restaurant =
                state.lastData?.[name];

            const code =
                restaurant?.currentRow
                    ?.canteenCode;

            const month =
                state.lastData?.latestMonth;

            if (!code || !month) {
                console.warn(
                    `${name} 缺少餐厅编码或月份`
                );
                return;
            }

            const excel =
                await fetchDetailExcel(
                    code,
                    month
                );

            downloadArrayBuffer(
                excel.arrayBuffer,
                `${name}_${month}_满意度详表.xls`
            );
        };

    window.stopSatisfactionMonitor =
        () => {
            state.running = false;

            if (state.refreshTimer) {
                clearTimeout(
                    state.refreshTimer
                );

                state.refreshTimer = null;
            }

            if (state.uiTimer) {
                clearInterval(
                    state.uiTimer
                );

                state.uiTimer = null;
            }

            if (
                state.pipWindow &&
                !state.pipWindow.closed
            ) {
                state.pipWindow.close();
            }

            delete window
                .__SATISFACTION_MONITOR__;

            delete window
                .__SATISFACTION_FLOAT_WINDOW__;

            const iframe = document.getElementById("satisfaction-float-iframe");
            if (iframe) iframe.remove();
            const closeBtn = document.getElementById("satisfaction-float-close");
            if (closeBtn) closeBtn.remove();
            const expandBtn = document.getElementById("satisfaction-float-expand");
            if (expandBtn) expandBtn.remove();
            const bubble = document.getElementById("satisfaction-monitor-bubble");
            if (bubble) bubble.remove();

            console.log(
                "满意度监控和浮窗已停止"
            );
        };

    /* =========================================================
     * 21. 启动
     * ========================================================= */

    window.addEventListener("message", async (event) => {
        if (event.data?.source === "EXTENSION_POPUP") {
            const action = event.data.action;
            if (action === "START") {
                if (state.running || window.__SATISFACTION_MONITOR__) {
                    console.log("检测到旧实例，先执行终止清理...");
                    window.stopSatisfactionMonitor();
                }
                state.running = true;
                console.log("正在启动 SV / CFC 满意度监控……");
                await openFloatWindow();
                runOnce();
            } else if (action === "STOP") {
                window.stopSatisfactionMonitor();
            }
        }
    });

    console.log(
        "默认排除工号前缀：",
        state.settings
            .excludedEmployeePrefixes
    );

    // Initial start if not running
    if (!window.__SATISFACTION_MONITOR__) {
        state.running = true;
        console.log("正在首次启动 SV / CFC 满意度监控……");
        await openFloatWindow();
        runOnce();
    }
})();

