document.getElementById('bank-storage-export-clean').onclick = () => {
    const selectedKeys = getSelectedStorageKeys();
    if (!selectedKeys.length) { alert(t('storageNeedSelect')); return; }
    const bankMap = new Map(listStoredQuestionBanks().map(bank => [bank.storageKey, bank]));
    const selectedBanks = selectedKeys.map(key => bankMap.get(key)).filter(Boolean);
    if (!selectedBanks.length) { alert(t('noData')); return; }
    if (!confirm(t('storageCleanConfirm', selectedBanks.map(bank => `• ${bank.name}`).join('\n')))) return;
    const before = calculateLocalStorageUsage();
    downloadQuestionBankBackup(selectedBanks);
    selectedBanks.forEach(bank => {
        localStorage.removeItem(bank.storageKey);
        storageScanCache.delete(bank.storageKey);
    });
    if (selectedKeys.includes(getStorageKey())) loadLocalData();
    refreshExamList();
    const after = calculateLocalStorageUsage();
    const freed = Math.max(0, before.totalBytes - after.totalBytes);
    const message = t('storageCleaned', selectedBanks.length, formatStorageBytes(freed), formatStorageBytes(after.availableBytes));
    renderBankStorageManager(message);
    logMsg(`🧹 ${message}`, 'success');
};
document.getElementById('bank-storage-clean-redundant').onclick = () => {
    const selectedKeys = getSelectedStorageKeys();
    if (!selectedKeys.length) { alert(t('storageNeedSelect')); return; }
    const bankMap = new Map(listStoredQuestionBanks().map(bank => [bank.storageKey, bank]));
    const before = calculateLocalStorageUsage();
    let cleanedCount = 0;
    for (const storageKey of selectedKeys) {
        const bank = bankMap.get(storageKey);
        if (!bank) continue;
        const scan = compactQuestionBankSafely(bank.questions);
        storageScanCache.set(storageKey, scan);
        if (scan.reclaimedBytes <= 0) continue;
        if (!persistQuestionBank(storageKey, scan.questions)) return;
        cleanedCount++;
    }
    if (selectedKeys.includes(getStorageKey())) loadLocalData();
    const after = calculateLocalStorageUsage();
    const freed = Math.max(0, before.totalBytes - after.totalBytes);
    const message = cleanedCount
        ? t('storageRedundantCleaned', cleanedCount, formatStorageBytes(freed), formatStorageBytes(after.availableBytes))
        : t('storageNoRedundant');
    renderBankStorageManager(message, selectedKeys);
    logMsg(`🧹 ${message}`, cleanedCount ? 'success' : 'info');
};

const importFileInput = document.getElementById('scraper-import-file');
document.getElementById('btn-import').onclick = () => {
    importFileInput.value = '';
    importFileInput.click();
};
importFileInput.onchange = async () => {
    const file = importFileInput.files && importFileInput.files[0];
    if (!file) return;
    try {
        const imported = JSON.parse(await file.text());
        const isBackupPackage = imported && typeof imported === 'object' && !Array.isArray(imported)
            && imported.format === QUESTION_BANK_BACKUP_FORMAT
            && Number(imported.version) === QUESTION_BANK_BACKUP_VERSION
            && Array.isArray(imported.banks);

        if (isBackupPackage) {
            const normalizedBanks = [];
            const seenNames = new Set();
            for (const bank of imported.banks) {
                const bankName = String(bank && bank.name || '').trim();
                if (!bankName || bankName.length > 200 || seenNames.has(bankName)) throw new Error('Invalid or duplicate bank name');
                seenNames.add(bankName);
                normalizedBanks.push({ name: bankName, questions: normalizeImportedQuestionArray(bank.questions) });
            }
            if (!normalizedBanks.length) throw new Error('Empty backup package');
            const totalQuestions = normalizedBanks.reduce((sum, bank) => sum + bank.questions.length, 0);
            const bankList = normalizedBanks.map(bank => `• ${bank.name} (${bank.questions.length})`).join('\n');
            if (!confirm(`${t('importBackupConfirm', normalizedBanks.length, totalQuestions)}\n\n${bankList}`)) return;
            const importEntries = normalizedBanks.map(bank => ({
                storageKey: `${QUESTION_BANK_STORAGE_PREFIX}${bank.name}`,
                questions: bank.questions
            }));
            if (!persistQuestionBanksAtomically(importEntries)) return;
            loadLocalData();
            refreshExamList();
            const successMessage = t('importBackupSuccess', normalizedBanks.length, totalQuestions);
            logMsg(successMessage, 'success');
            alert(successMessage);
        } else {
            if (!examNameInput.value.trim()) { alert(t('needName')); return; }
            const normalized = normalizeImportedQuestionArray(imported);
            if (!confirm(t('importConfirm', examNameInput.value.trim()))) return;
            if (!persistQuestionBank(getStorageKey(), normalized)) return;
            loadLocalData();
            refreshExamList();
            logMsg(t('importSuccess', normalized.length), 'success');
            alert(t('importSuccess', normalized.length));
        }
    } catch (error) {
        console.warn('[Exam Scraper] Import failed:', error);
        alert(t('importInvalid'));
        logMsg(t('importInvalid'), 'warn');
    }
};
})();

(function authorizedMediaExporter() {
  'use strict';

  const PANEL_ID = 'tools-authorized-media-exporter';
  const STYLE_ID = `${PANEL_ID}-style`;
  const MEDIA_PATTERN = /\.(?:m3u8|mp4|webm|mov)(?:$|[?#])/i;
  const state = { items: [] };

  function removeExporter() {
    document.getElementById(PANEL_ID)?.remove();
    document.getElementById(STYLE_ID)?.remove();
    window.removeEventListener('message', handleExtensionMessage);
    delete window.__toolsAuthorizedMediaExporterCleanup;
  }

  if (typeof window.__toolsAuthorizedMediaExporterCleanup === 'function') {
    window.__toolsAuthorizedMediaExporterCleanup();
  }
  window.__toolsAuthorizedMediaExporterCleanup = removeExporter;

  function handleExtensionMessage(event) {
    if (event.source !== window || event.data?.source !== 'EXTENSION_POPUP') return;
    if (event.data.action === 'STOP') removeExporter();
  }
  window.addEventListener('message', handleExtensionMessage);

  function normalizeUrl(value) {
    try {
      const url = new URL(String(value || '').trim(), location.href);
      if (!['http:', 'https:'].includes(url.protocol) || !MEDIA_PATTERN.test(url.href)) return '';
      return url.href;
    } catch (_error) {
      return '';
    }
  }

  function cleanFilePart(value, fallback) {
    const cleaned = String(value || '')
      .normalize('NFKC')
      .replace(/[\u0000-\u001f<>:"/\\|?*]+/g, '_')
      .replace(/\s+/g, ' ')
      .trim()
      .replace(/^\.+|\.+$/g, '')
      .slice(0, 120);
    return cleaned || fallback;
  }

  function guessTitle(element, index) {
    const container = element?.closest?.('[data-title], article, li, section');
    return cleanFilePart(
      element?.getAttribute?.('data-title')
        || element?.getAttribute?.('title')
        || element?.getAttribute?.('aria-label')
        || container?.getAttribute?.('data-title')
        || container?.querySelector?.('h1,h2,h3,h4')?.textContent
        || document.title,
      `视频_${index + 1}`
    );
  }

  function collectVisibleMedia() {
    const candidates = [];
    document.querySelectorAll('video, video source').forEach((element, index) => {
      ['src', 'data-src', 'data-video-src', 'data-url'].forEach(attribute => {
        const url = normalizeUrl(element.getAttribute(attribute));
        if (url) candidates.push({ url, title: guessTitle(element, index), source: '页面媒体' });
      });
      if (element.currentSrc) {
        const url = normalizeUrl(element.currentSrc);
        if (url) candidates.push({ url, title: guessTitle(element, index), source: '当前播放' });
      }
    });
    performance.getEntriesByType('resource').forEach((entry, index) => {
      const url = normalizeUrl(entry.name);
      if (url) candidates.push({ url, title: `网络媒体_${index + 1}`, source: '页面网络记录' });
    });
    return candidates;
  }

  function mergeCandidates(candidates) {
    const existing = new Map(state.items.map(item => [item.url, item]));
    candidates.forEach(candidate => {
      if (!candidate.url || existing.has(candidate.url)) return;
      const item = { ...candidate, selected: true };
      state.items.push(item);
      existing.set(item.url, item);
    });
  }

  function parseManualInput(value) {
    return String(value || '').split(/\r?\n/).map((line, index) => {
      const trimmed = line.trim();
      if (!trimmed) return null;
      const separator = trimmed.indexOf('|');
      const title = separator >= 0 ? trimmed.slice(0, separator).trim() : `手动媒体_${index + 1}`;
      const rawUrl = separator >= 0 ? trimmed.slice(separator + 1).trim() : trimmed;
      const url = normalizeUrl(rawUrl);
      return url ? { url, title: cleanFilePart(title, `手动媒体_${index + 1}`), source: '手动输入' } : null;
    }).filter(Boolean);
  }

  function shellQuote(value) {
    return `'${String(value).replace(/'/g, `'"'"'`)}'`;
  }

  function buildDownloadScript(items, directoryName) {
    const outputDirectory = cleanFilePart(directoryName, '课程视频');
    const referer = `${location.origin}/`;
    const lines = [
      '#!/usr/bin/env bash',
      'set -euo pipefail',
      '',
      'if ! command -v ffmpeg >/dev/null 2>&1; then',
      '  echo "未找到 ffmpeg，请先安装后重试。" >&2',
      '  exit 1',
      'fi',
      '',
      `OUTPUT_DIR="$HOME/Downloads/${outputDirectory.replace(/[$`"\\]/g, '_')}"`,
      'mkdir -p "$OUTPUT_DIR"',
      'cd "$OUTPUT_DIR"',
      ''
    ];
    items.forEach((item, index) => {
      const order = String(index + 1).padStart(3, '0');
      const extension = /\.webm(?:$|[?#])/i.test(item.url) ? 'webm' : /\.mov(?:$|[?#])/i.test(item.url) ? 'mov' : 'mp4';
      const fileName = `${order}_${cleanFilePart(item.title, `视频_${order}`)}.${extension}`;
      lines.push(`echo ${shellQuote(`正在下载 ${index + 1}/${items.length}：${item.title}`)}`);
      lines.push(`ffmpeg -nostdin -hide_banner -loglevel warning -stats -headers ${shellQuote(`Referer: ${referer}\r\n`)} -i ${shellQuote(item.url)} -c copy -y ${shellQuote(fileName)}`);
      lines.push('');
    });
    lines.push('echo "全部任务完成。"');
    return lines.join('\n');
  }

  function downloadText(content, fileName) {
    const url = URL.createObjectURL(new Blob([content], { type: 'text/x-shellscript;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  function renderItems() {
    const list = document.querySelector(`#${PANEL_ID} [data-role="list"]`);
    const status = document.querySelector(`#${PANEL_ID} [data-role="status"]`);
    list.replaceChildren();
    state.items.forEach((item, index) => {
      const row = document.createElement('label');
      row.className = 'tam-row';
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = item.selected;
      checkbox.addEventListener('change', () => { item.selected = checkbox.checked; updateStatus(); });
      const main = document.createElement('span');
      main.className = 'tam-row-main';
      const title = document.createElement('input');
      title.className = 'tam-title-input';
      title.value = item.title;
      title.addEventListener('input', () => { item.title = title.value; });
      const meta = document.createElement('small');
      meta.textContent = `${item.source} · ${item.url}`;
      main.append(title, meta);
      row.append(checkbox, main);
      list.appendChild(row);
    });
    status.textContent = state.items.length ? '' : '尚未发现可直接访问的媒体地址。可先播放视频后重新扫描，或手动粘贴直链。';
    updateStatus();
  }

  function updateStatus(message) {
    const status = document.querySelector(`#${PANEL_ID} [data-role="status"]`);
    if (!status) return;
    if (message) {
      status.textContent = message;
