(async function() {
  console.log("🔍 正在全自动嗅探当前课程信息，无需手动输入...");

  // 1. 从浏览器已发出的网络请求流中，自动捕获 liveId 和 channelId
  let liveId = null;
  let channelId = null;

  for (const entry of performance.getEntriesByType("resource")) {
    const url = entry.name;
    if (!liveId) {
      const match = url.match(/[?&]liveId=([0-9]+)/i);
      if (match) liveId = match[1];
    }
    if (!channelId) {
      const match = url.match(/[?&]channelId=([0-9]+)/i) || url.match(/[?&]businessId=([0-9]+)/i);
      if (match) channelId = match[1];
    }
    if (liveId && channelId) break;
  }

  // 兜底：如果刚打开页面没捕获全，从页面参数获取
  if (!channelId) {
    const p = new URLSearchParams(location.search);
    channelId = p.get("channelId");
  }

  if (!liveId || !channelId) {
    console.error("❌ 未能在当前页面自动探测到 ID，请尝试刷新页面后重新运行本脚本。");
    return;
  }

  console.log(`🎯 自动嗅探成功 -> liveId: ${liveId} | channelId: ${channelId}`);

  // 2. 自动获取这门课程的专栏官方名称（作为文件夹名）
  let courseName = "千聊课程";
  try {
    const profileRes = await fetch(`https://h5.qlchat.com/api/wechat/channel/profile?channelId=${channelId}`).then(r => r.json());
    if (profileRes?.data?.name || profileRes?.data?.topic) {
      courseName = (profileRes.data.name || profileRes.data.topic).replace(/[/\\:*?"<>|]/g, "_").trim();
    }
  } catch (e) {
    courseName = document.title.replace(/[-_|].*千聊.*$/i, "").trim().replace(/[/\\:*?"<>|]/g, "_") || "千聊课程";
  }

  console.log(`📚 识别课程名称: 《${courseName}》`);

  // 3. 密钥配置与解密函数
  const KEY_STR = "711AAB17E204816B783374025FD08DE8";
  const IV_STR = "0102030405060708";

  async function decryptUrl(cipherBase64) {
    const enc = new TextEncoder();
    const key = await crypto.subtle.importKey("raw", enc.encode(KEY_STR), { name: "AES-CBC" }, false, ["decrypt"]);
    const iv = enc.encode(IV_STR);
    const rawData = Uint8Array.from(atob(cipherBase64), c => c.charCodeAt(0));
    const decrypted = await crypto.subtle.decrypt({ name: "AES-CBC", iv: iv }, key, rawData);
    return new TextDecoder().decode(decrypted);
  }

  // 4. 全自动遍历翻页拉取所有小节目录
  let allCourses = [];
  let page = 1;
  while (true) {
    try {
      const res = await fetch("https://h5.qlchat.com/api/wechat/transfer/h5/interact/getCourseList", {
        method: "POST",
        headers: { "content-type": "application/json;charset=UTF-8" },
        body: JSON.stringify({
          channelId: channelId,
          sort: "asc",
          liveId: liveId,
          page: { page: page, size: 20 }
        })
      }).then(r => r.json());

      const list = res?.data?.dataList;
      if (list && list.length > 0) {
        allCourses = allCourses.concat(list);
        page++;
      } else {
        break;
      }
    } catch (e) {
      break;
    }
  }

  console.log(`📋 共获取到 ${allCourses.length} 节课程目录，正在批量解析真实播放地址...`);

  // 生成防冲突、跳过已下载的 bash 命令
  let bashCommands = [
    '#!/bin/bash',
    `mkdir -p ~/Desktop/"${courseName}"`,
    `cd ~/Desktop/"${courseName}"\n`
  ];

  // 5. 循环解析每一个视频真实链接
  for (let i = 0; i < allCourses.length; i++) {
    const item = allCourses[i];
    const topicId = item.businessId || item.topicPo?.id;
    const title = (item.businessName || item.topicPo?.topic || `第${i+1}课`).replace(/[/\\:*?"<>|]/g, "_");
    const order = String(i + 1).padStart(2, '0');
    const fileName = `${order}_${title}.mp4`;

    try {
      const mediaRes = await fetch("https://h5.qlchat.com/api/wechat/topic/getMediaActualUrl", {
        method: "POST",
        headers: { "content-type": "application/json;charset=UTF-8" },
        body: JSON.stringify({ topicId: String(topicId) })
      }).then(r => r.json());

      const playUrlCipher = mediaRes?.data?.video?.[0]?.playUrl;
      if (playUrlCipher) {
        const realM3u8 = await decryptUrl(playUrlCipher);
        console.log(`[${i+1}/${allCourses.length}] ✅ 解密成功: ${title}`);
        bashCommands.push(`echo "正在下载 [${i+1}/${allCourses.length}]: ${title}..."`);
        bashCommands.push(`ffmpeg -n -headers "Referer: https://h5.qlchat.com/\\r\\n" -i "${realM3u8}" -c copy "${fileName}"`);
      } else {
        console.warn(`[${i+1}/${allCourses.length}] ⚠️ 非视频（作业/图文）: ${title}`);
      }
    } catch (err) {
      console.error(`[${i+1}/${allCourses.length}] ❌ 失败: ${title}`, err);
    }
    await new Promise(r => setTimeout(r, 120));
  }

  // 6. 自动导出下载脚本
  const blob = new Blob([bashCommands.join("\n")], { type: "text/plain" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `download_${courseName}.sh`;
  a.click();
  console.log(`🎉 全部解析完毕！下载脚本 download_${courseName}.sh 已自动保存到下载文件夹！`);
})();

